'use strict';
let walkDestinationDrag=null;
function selectedWalkBlock(){const o=object();if(!isAnimatedCharacter(o)||o.locked||canvasMode!=='select'||pathEditor)return null;return o.actionBlocks?.find(b=>b.id===selectedActionId&&b.type==='walk')||o.actionBlocks?.filter(b=>b.type==='walk'&&time>=b.start&&time<=b.start+b.duration).at(-1)||null}
function canvasWorldPixel(){return 960/Math.max(1,$('stage').getBoundingClientRect().width)/cameraAt(current(),time).zoom}
function drawWalkDestination(){if(playing||recording)return;const block=selectedWalkBlock();if(!block?.to||!block.from)return;const unit=canvasWorldPixel(),c=ctx;c.save();applyCamera(c,current(),time);c.setLineDash([6*unit,4*unit]);line(c,block.from.x,block.from.y,block.to.x,block.to.y,'#82e1cf',1.5*unit);c.setLineDash([]);circle(c,block.from.x,block.from.y,5*unit,'#18232a');circle(c,block.to.x,block.to.y,10*unit,'#80e1cd');circle(c,block.to.x,block.to.y,5*unit,'#132421');c.font=12*unit+'px Arial';c.textAlign='center';c.fillStyle='#ffffff';c.strokeStyle='#11151b';c.lineWidth=4*unit;c.strokeText('Drag destination',block.to.x,block.to.y-18*unit);c.fillText('Drag destination',block.to.x,block.to.y-18*unit);c.restore()}
const downBeforeWalkDestination=$('stage').onpointerdown,moveBeforeWalkDestination=$('stage').onpointermove,upBeforeWalkDestination=$('stage').onpointerup,cancelBeforeWalkDestination=$('stage').onpointercancel;
$('stage').onpointerdown=e=>{const block=selectedWalkBlock(),p=pointerWorld(e,null);if(e.button===0&&!recording&&block&&Math.hypot(p.x-block.to.x,p.y-block.to.y)<15*canvasWorldPixel()){stop();walkDestinationDrag={block,actor:object(),before:structuredClone(block.to),scene:current(),project,camera:cameraAt(current(),time)};window.canvasDragBusy=true;$('stage').setPointerCapture(e.pointerId);e.preventDefault();draw();return}downBeforeWalkDestination?.(e)};
$('stage').onpointermove=e=>{if(!walkDestinationDrag)return moveBeforeWalkDestination?.(e);const drag=walkDestinationDrag;if(project!==drag.project||current()!==drag.scene||drag.actor.locked)return finishWalkDestination(true);const p=pointerWorld(e,drag);drag.block.to={x:clamp(p.x,0,960),y:clamp(p.y,0,540)};draw()};
function finishWalkDestination(cancel=false){const drag=walkDestinationDrag;walkDestinationDrag=null;window.canvasDragBusy=false;if(!drag)return;if(cancel)drag.block.to=drag.before;else if(Math.hypot(drag.before.x-drag.block.to.x,drag.before.y-drag.block.to.y)>.01)save();render()}
$('stage').onpointerup=e=>walkDestinationDrag?finishWalkDestination():upBeforeWalkDestination?.(e);$('stage').onpointercancel=e=>walkDestinationDrag?finishWalkDestination(true):cancelBeforeWalkDestination?.(e);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&walkDestinationDrag){e.preventDefault();finishWalkDestination(true)}});
const drawBeforeDirectMotion=draw;draw=function(){drawBeforeDirectMotion();drawWalkDestination()};
const controlsBeforeDirectMotion=renderControls;renderControls=function(){controlsBeforeDirectMotion();const o=object();if(!o)return;const panel=document.createElement('details');panel.innerHTML='<summary>Movement on canvas</summary><button id="directMotionPath">'+(o.motionPath?'Edit route points':'Draw a route')+'</button>'+(isAnimatedCharacter(o)?'<button id="directWalkDestination">Adjust walking destination</button>':'')+'<p class="note">Route points and walking destinations can be dragged directly. Esc cancels a drag. Changes can be undone.</p>';panel.querySelectorAll('button').forEach(b=>b.disabled=!!o.locked);$('controls').append(panel);$('directMotionPath').onclick=()=>beginPathEditing('layer');if($('directWalkDestination'))$('directWalkDestination').onclick=()=>{const block=o.actionBlocks?.filter(b=>b.type==='walk').find(b=>b.id===selectedActionId)||o.actionBlocks?.filter(b=>b.type==='walk').at(-1);if(!block)return startWalkClick(o);stop();canvasMode='select';selectedActionId=block.id;time=block.start;render();toast('Drag the mint destination handle on the canvas.')}};
